from pyspark.sql import functions as F


def make_tasks(shipments, shipment_events, deliveries):
    def clean_events():
        # One row per event: the copies of a re-sent event differ only in load_date.
        return shipment_events.select([c for c in shipment_events.columns if c != "load_date"]).distinct()

    def known_events(clean_events):
        ids = [r.shipment_id for r in shipments.select("shipment_id").collect()]
        unknown = clean_events.filter(~F.coalesce(F.col("shipment_id").isin(ids), F.lit(False))).count()
        if unknown > 0:
            raise ValueError(f"{unknown} events for unknown shipments")
        return clean_events

    def delivered(known_events):
        return known_events.filter(F.col("event_type") == "delivered")

    def late_deliveries():
        return deliveries.filter(F.col("status") == "late")

    def late_scans(delivered, late_deliveries):
        late_ids = [r.shipment_id for r in late_deliveries.select("shipment_id").collect()]
        return delivered.filter(F.col("shipment_id").isin(late_ids))

    def carrier_report(late_scans, carrier_scores):
        return late_scans

    def carrier_scores(carrier_report):
        return carrier_report

    def weekly_email(carrier_report):
        return carrier_report

    def in_flight(delivered, todays_shipments):
        done = [r.shipment_id for r in delivered.select("shipment_id").collect()]
        return todays_shipments.filter(~F.col("shipment_id").isin(done))

    return {
        "weekly_email": (weekly_email, ["carrier_report"]),
        "in_flight": (in_flight, ["delivered", "todays_shipments"]),
        "carrier_scores": (carrier_scores, ["carrier_report"]),
        "carrier_report": (carrier_report, ["late_scans", "carrier_scores"]),
        "late_scans": (late_scans, ["delivered", "late_deliveries"]),
        "delivered": (delivered, ["known_events"]),
        "known_events": (known_events, ["clean_events"]),
        "late_deliveries": (late_deliveries, []),
        "clean_events": (clean_events, []),
    }


def solve(shipments, shipment_events, deliveries):
    tasks = make_tasks(shipments, shipment_events, deliveries)
    deps = {name: needs for name, (fn, needs) in tasks.items()}
    # Find the tasks that can never run, then run the others and give every task a status.
    status = {}
    return spark.createDataFrame(list(status.items()), "task STRING, status STRING")
